function longestUnique(log: string): number {
  const last = new Map<string, number>();
  let start = 0, best = 0;
  for (let i = 0; i < log.length; i++) {
    const prev = last.get(log[i]);
    if (prev !== undefined && prev >= start) start = prev + 1;
    last.set(log[i], i);
    best = Math.max(best, i - start + 1);
  }
  return best;
}
